import * as E from './engine.mjs';
import {FUTURE} from './future.mjs';
import {L,STORIES,SOURCES,chaptersFor,carDefaults,price} from './data.mjs';
import {icon,town,miniArt,scene} from './art.mjs';
const KEY='save-your-story-v1';
let state=E.initialState(),page='home',storyView='journal',financeView='profile',previewId=null,onboardStep=0,formDraft={},focusBeforeModal=null,saveFailure=false;
try{const saved=localStorage.getItem(KEY);if(saved)state=E.validateImport(JSON.parse(saved));}catch{saveFailure=true;}
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=(en,zh)=>state.language==='zh'?(zh||en):en;
const tx=v=>typeof v==='object'&&v!==null?esc(v[state.language]||v.en):esc(v);
const profile=()=>E.activeProfile(state);
const active=()=>E.session(state);
const story=id=>STORIES.find(s=>s.id===id);
const cash=(v,currency=profile()?.currency||'MYR')=>`${currency==='MYR'?'RM':'S$'}${Number(v||0).toLocaleString(state.language==='zh'?'zh-CN':'en-SG',{maximumFractionDigits:2,minimumFractionDigits:Number(v)%1?2:0})}`;
const date=d=>new Date(d+'T12:00:00Z').toLocaleDateString(state.language==='zh'?'zh-CN':'en-GB',{day:'numeric',month:'short',year:'numeric'});
const button=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const badge=(s,cls='')=>`<span class="badge ${cls}">${s}</span>`;
const progress=(value,max,cls='')=>`<div class="progress ${cls}" role="progressbar" aria-label="${tr('Savings progress','储蓄进度')}" aria-valuemin="0" aria-valuemax="${max||1}" aria-valuenow="${Math.min(value,max||1)}"><span style="width:${Math.min(100,Math.max(0,value/(max||1)*100))}%"></span></div>`;
const notice=(s,cls='')=>`<div class="notice ${cls}">${s}</div>`;
const field=(label,name,value,type='number',hint='',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01" inputmode="decimal"':''} ${attrs}>${hint?`<small>${hint}</small>`:''}</label>`;
const select=(label,name,value,options,hint='')=>`<label class="field">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select>${hint?`<small>${hint}</small>`:''}</label>`;
const formError='<div class="form-error error" role="alert"></div>';
const ACTS=[L('The beginning','开始'),L('The preparation','准备'),L('The turning point','转折'),L('The responsibility','责任'),L('The achievement','成就')];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveFailure=false;return true;}catch{saveFailure=true;toast(tr('Device storage is unavailable or full. Export your progress now.','设备储存不可用或已满。请立即导出进度。'));return false;}}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function openModal(title,body){const d=$('#modal');focusBeforeModal=document.activeElement;d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="iconbtn" data-action="close" aria-label="${tr('Close','关闭')}">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();d.scrollTop=0;}
function closeModal(){$('#modal').close();focusBeforeModal?.focus?.();}
function navigate(p){page=p;render();window.scrollTo({top:0,behavior:'smooth'});}
function header(eyebrow,title,sub,side=''){return `<div class="page-head"><div>${eyebrow?`<div class="eyebrow muted mb" style="margin-bottom:9px">${eyebrow}</div>`:''}<h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${side}</div>`;}
function render(){document.documentElement.lang=state.language==='zh'?'zh-Hans':'en';const navs=[['home','Home','首页'],['story','Story','故事'],['finance','Finance','财务'],['savings','Savings','储蓄'],['profile','Profile','我的']];const p=profile();$('#app').innerHTML=`
<aside class="sidebar"><a class="brand" href="#home" data-action="nav:home"><img src="icon.svg" alt=""><span>Save Your<br>Story<small>${tr('A life worth saving for','为值得的生活而储蓄')}</small></span></a><nav class="nav" aria-label="${tr('Primary navigation','主要导航')}">${navs.map(([id,en,zh])=>`<button data-action="nav:${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${tr(en,zh)}</span></button>`).join('')}</nav><div class="sidebar-note">${icon('leaf')}<p>${tr('“Little by little,<br>a little becomes a lot.”','“一点一滴，<br>终将积少成多。”')}</p><small>${tr('YOUR PACE. YOUR STORY.','你的节奏，你的故事。')}</small></div><div class="user-chip"><div class="avatar">${esc(state.name[0]?.toUpperCase()||'A')}</div><div><span class="small bold">${esc(state.name)}</span><small>${tr('Local demo · this device','本地演示 · 此设备')}</small></div></div></aside>
<div class="shell"><div class="topbar"><div class="crumb"><span>${tr('My life journal','我的生活日记')} &nbsp;/&nbsp; </span><b>${tr(navs.find(n=>n[0]===page)[1],navs.find(n=>n[0]===page)[2])}</b></div><div class="top-actions"><span class="date">${date(E.today())}</span><button class="lang" data-action="language">${state.language==='en'?'EN / 中文':'中文 / EN'}</button><button class="iconbtn" data-action="reminders" aria-label="${tr('Reminders','提醒')}">${icon('bell')}</button></div></div><main id="main" tabindex="-1">${saveFailure?notice(tr('Your saved data could not be read or written. Keep a backup before closing this page.','无法读取或写入保存数据。关闭页面前请备份。'),'warn')+'<br>':''}${({home:homePage,story:storyPage,finance:financePage,savings:savingsPage,profile:profilePage}[page])()}</main><div class="footer-note">${icon('leaf')}${tr('Play your future. Build your savings. Live your story.','体验未来，积累储蓄，书写人生。')}<br>${tr('Your money stays with you. Progress is saved on this browser only.','资金由你保管。进度仅保存在此浏览器。')}</div></div>`;}
function homePage(){const p=profile(),s=active(),c=s&&!s.completed?chaptersFor(s.story,s.country,s.config)[s.index]:null,st=s?story(s.story):null;const total=p?E.recordedSavings(state,p):0;const emergency=p?E.reserves(state,p):0;const target=p?(p.fixed+p.living+p.loans)*state.emergency.months:9000;const ch=s?.current;return `${header(tr('YOUR EVERYDAY, REIMAGINED','重新想象你的日常'),tr(`Hello, ${esc(state.name)}. Let’s grow a little.`,`你好，${esc(state.name)}。一起成长一点。`),tr('Big life moments begin with the small things you do today.','人生的重要时刻，始于今天的小小行动。'),badge(icon('leaf')+tr('One chapter at a time','一章一章，慢慢来')))}
<div class="home-layout"><section class="world"><div class="paper-foot"></div><div class="world-heading"><div><h2>${s?tr('Your next chapter is taking shape.','你的下一章，正慢慢成形。'):tr('A little town. A world of possibility.','一座小镇，无限可能。')}</h2><p>${tr('There’s a whole life waiting to be lived.','有一整个人生，等你去体验。')}</p></div>${badge(icon('sun')+tr('A fresh beginning','新的开始'),'neutral')}</div><div class="world-art">${town()}</div><div class="world-footer"><div class="chapter-icon">${icon(st?.icon||'story')}</div><div class="grow"><h3>${s?tx(st.title):tr('Your story starts here','你的故事从这里开始')}</h3><p>${s?(s.completed?tr('A chapter closed. A new beginning awaits.','一段旅程结束，新的开始正等着你。'):tr(`Chapter ${s.index+1} · `,`第${s.index+1}章 · `)+tx(c.title)):tr('Choose a little dream to grow into.','选一个小小的梦想，慢慢实现。')}</p></div>${button(s?tr('Continue story','继续故事'):tr('Begin your story','开始你的故事'),s?'nav:story':'onboard')}</div></section><div class="side-cards"><section class="card saving-card"><div class="eyebrow">${tr('YOUR REAL SAVINGS','你的真实储蓄')}</div><span class="coin">${icon('coin')}</span><h3>${cash(total)}</h3><p>${p?tr('Recorded by you. Kept by you.','由你记录，由你保管。'):tr('Your first small step is waiting.','等待你的第一小步。')}</p>${progress(p?E.accepted(state,p.currency).reduce((n,t)=>n+t.main,0):0,Math.max(ch?.requiredTotal||1,1000))}<button class="textbtn" data-action="nav:savings">${tr('Open your savings journal','打开储蓄日记')}</button></section><section class="card"><div class="flex gap8"><div class="round-icon">${icon('calendar')}</div><h3>${tr('Savings Day','储蓄日')}</h3></div><div class="mini-calendar"><strong>${ch?Math.max(0,ch.dueDay-s.clock):'—'}</strong><div class="small">${ch?tr('story days to checkpoint','个故事日后到达储蓄点'):tr('Your next small milestone','你的下一个小里程碑')}<br><span class="muted">${ch?cash(Math.max(0,ch.requiredTotal-E.allocation(state,s.id,s.currency)),s.currency):(s?tr('Make a choice in your chapter','在当前章节做个选择'):tr('Choose a story to begin','选择故事即可开始'))}</span></div></div><p class="small muted">${tr('A moment to pause, save, and keep going.','停一停，存一点，再向前。')}</p><div class="mt12">${button(tr('Visit Savings Day','前往储蓄日'),'nav:savings','secondary smallbtn')}</div></section></div></div>
<div class="section-head"><h2>${tr('What will your next chapter be?','你的下一章，会是什么？')}</h2><button class="textbtn" data-action="library">${tr('Explore all stories','探索所有故事')}</button></div><div class="story-strip">${STORIES.slice(0,3).map(s=>storyCard(s)).join('')}</div>
<div class="home-bottom"><section class="card flex"><svg class="meter-ring" viewBox="0 0 60 60" aria-hidden="true"><circle cx="30" cy="30" r="24" fill="none" stroke="#e2e8d8" stroke-width="5"/><circle cx="30" cy="30" r="24" fill="none" stroke="#879d79" stroke-width="5" stroke-dasharray="${Math.min(1,emergency/(target||1))*151} 151"/></svg><div class="grow"><div class="small bold">${tr('A softer landing','安心的依靠')}</div><p class="small muted">${tr('Your emergency fund','你的应急基金')} · ${cash(emergency)} / ${cash(target)}</p></div><button class="iconbtn" data-action="emergency" aria-label="${tr('Manage emergency fund','管理应急基金')}">${icon('plant')}</button></section><section class="card flex"><div class="round-icon" style="background:#e7edf0;color:#637e8e">${icon('shield')}</div><div><div class="small bold">${tr('Real life & story life, thoughtfully apart','真实生活与故事生活，清楚分开')}</div><p class="small muted">${tr('A virtual expense never moves your real money.','虚拟开支不会动用你的真实资金。')}</p></div></section></div>`;}
function storyCard(s,library=false){return `<button class="story-mini" data-action="preview:${s.id}"><div class="mini-art ${s.color}">${miniArt(s.icon)}</div><div class="mini-body">${library?`<div class="flex between mb" style="margin-bottom:12px">${badge(s.playable?tr('Playable V1','V1可玩'):tr('In development','开发中'),s.playable?'':'neutral')}</div>`:''}<h3>${tx(s.title)}</h3><p>${tx(s.subtitle)}</p><div class="flex between mt12"><span class="small muted" style="font-size:.75rem">${icon('clock').replace('class="icon','style="width:13px;height:13px;vertical-align:-2px;margin-right:4px" class="icon')}${tx(s.duration)}</span>${!library?badge(tr('Explore story','探索故事'),s.color):''}</div></div></button>`;}
function storyPage(){const s=active();const tabbar=`<div class="tabs"><button data-action="storyview:journal" class="${storyView==='journal'?'active':''}">${tr('My story','我的故事')}</button><button data-action="storyview:library" class="${storyView==='library'?'active':''}">${tr('Story library','故事书库')} · 10</button></div>`;if(storyView==='library')return header(tr('A LIFE FULL OF POSSIBILITIES','充满可能的人生'),tr('Every dream has a first page.','每个梦想，都有第一页。'),tr('One main story. A safety net alongside it. Your own pace.','一个主线故事，一份并行应急计划。按自己的节奏。'))+tabbar+`<div class="library">${STORIES.map(s=>storyCard(s,true)).join('')}</div>`;
if(!s)return header('',tr('A blank page, a new beginning.','空白的一页，崭新的开始。'),tr('Choose the future you would like to try on.','选择一个想体验的未来。'))+tabbar+`<section class="card text-center">${miniArt('book')}<h2>${tr('Which story feels like you?','哪个故事，最像你？')}</h2><p class="muted mt12">${tr('Four journeys are ready to play. Six more are taking shape.','四段旅程已可体验，另外六段正在构思中。')}</p><div class="mt">${button(tr('Find my first story','寻找我的第一个故事'),'library')}</div></section>`;
if(s.completed)return header(tr('THE ACHIEVEMENT','成就'),tx(story(s.story).title),tr('You made it, one small decision at a time.','一个个小小的决定，带你走到这里。'))+tabbar+`<section class="card text-center"><div class="story-preview-art">${miniArt(story(s.story).icon)}</div><h2>${tr('This chapter belongs to you.','这一章，属于你。')}</h2><p class="muted mt12">${s.history.length} ${tr('chapters experienced','个章节已体验')} · ${cash(E.allocation(state,s.id,s.currency),s.currency)} ${tr('self-recorded savings','自行记录的储蓄')}</p>${s.story==='car'?notice(tr(`The story ends after two years. Your modelled remaining principal is ${cash(E.remainingLoan(s.config,20).principal,s.currency)}; scheduled future repayments total ${cash(E.remainingLoan(s.config,20).scheduledPayments,s.currency)}. Settlement quotes may differ.`,`故事在两年后结束。模拟剩余本金为${cash(E.remainingLoan(s.config,20).principal,s.currency)}，未来计划供款总额为${cash(E.remainingLoan(s.config,20).scheduledPayments,s.currency)}。实际结清报价可能不同。`),'warn'):''}<div class="mt">${button(tr('Choose another chapter','选择新的旅程'),'library')}</div></section>`+history(s);
const chapters=chaptersFor(s.story,s.country,s.config),c=chapters[s.index],p=profile(),cur=s.current,event=E.eventFor(s);const days=cur?Math.max(0,cur.dueDay-s.clock):0;const saved=E.allocation(state,s.id,s.currency),left=cur?Math.max(0,cur.requiredTotal-saved):0;return `${header(tx(story(s.story).title),tx(c.title),tr(`Chapter ${s.index+1} of ${chapters.length} · Story day ${s.clock}`,`第${s.index+1}章，共${chapters.length}章 · 故事第${s.clock}天`),badge(tr('Story life · simulated','故事生活 · 模拟'),'blue'))}${tabbar}<div class="journal-layout"><div><section class="scene"><div class="scene-art">${scene({scene:c.scene,month:c.month,language:state.language,twins:s.index>0&&s.twins})}</div><div class="scene-caption"><div class="act-label">${tr('Act','幕')} ${c.act+1} · ${tx(ACTS[c.act])}</div><h2 class="mt8">${tx(c.title)}</h2></div></section><p class="dialogue">${tx(c.intro)}</p>${s.story==='baby'?notice(tr('Budget scenes, not a medical schedule. Configure timing and quotations with your care team. Never delay necessary treatment for a game checkpoint.','这是预算情景，并非医疗时间表。请与照护团队设定时间和报价。不要为了游戏而推迟必要治疗。'),'blue'):''}${s.story==='baby'&&s.index===1?`<div class="notice mt12">${s.twins?tr('Your persisted story branch: twins. Only applicable costs increase.','已保存的故事分支：双胎。仅相关成本增加。'):tr('Your persisted story branch: one baby.','已保存的故事分支：单胎。')} ${tr('The 1% twin roll is a game mechanic, not a medical statistic.','1%的双胎概率是游戏设定，并非医学统计。')}</div>`:''}
${cur?`<section class="card mt"><div class="flex between"><div><div class="eyebrow muted">${tr('YOUR DECISION','你的决定')}</div><h3 class="mt8">${tx(cur.choice.title)}</h3></div>${badge(icon('check')+tr('Saved','已保存'))}</div><p class="small muted mt12">${tx(cur.choice.detail)}</p><hr class="rule"><div class="flex between"><span class="small">${tr('This chapter’s savings checkpoint','本章储蓄目标')}</span><strong>${cash(cur.target,s.currency)}</strong></div><div class="mt12">${progress(Math.min(cur.target,Math.max(0,saved-(cur.requiredTotal-cur.target))),cur.target||1)}</div><p class="small muted mt12">${left?tr(`${cash(left,s.currency)} left to record. Deposits must be explicitly self-confirmed.`,`还需记录${cash(left,s.currency)}。存款须由你明确确认。`):tr('Savings requirement met. Your funds remain in your own account.','储蓄条件已满足。资金仍在你自己的账户。')}</p>${cur.shortfall?`<div class="mt12">${notice(tr(`This checkpoint is reduced by ${cash(cur.shortfall,s.currency)} to fit current capacity. It does not establish affordability. Extend preparation, lower the target, or postpone.`,`此目标按当前能力下调了${cash(cur.shortfall,s.currency)}。这不代表能负担该计划。请延长准备期、降低目标或推迟。`),'warn')}</div>`:''}<div class="form-actions">${left>0?button(tr('Record my savings','记录我的储蓄'),'deposit','secondary'):''}${button(tr('Adjust checkpoint','调整储蓄点'),'adjustcheckpoint','secondary')}${days>0?button(tr(`Advance ${days} story days`,`推进${days}个故事日`),'clock','secondary'):''}${button(tr('Turn the page','翻开下一页'),'advance','',E.canAdvance(state,s)?'':'disabled')}</div><p class="tiny muted mt12">${tr('Advancing the story calendar only changes simulated time. Actual income and dates stay under your control.','推进故事日历只会改变模拟时间。真实收入与日期由你掌控。')}</p></section>`:`<div class="section-head"><h3>${tr('What feels right for you?','你会如何选择？')}</h3><span class="small muted">${tr('Your choices matter.','你的选择，会有影响。')}</span></div><div class="decisions">${c.choices.map(q=>`<button class="decision" data-action="decide:${q.id}"><span class="choice-circle"></span><span><strong>${tx(q.title)}</strong><small>${tx(q.detail)}</small></span></button>`).join('')}</div>`}
${event?`<section class="event mt"><div class="eyebrow muted">${tr('LIFE HAPPENS','生活中的小插曲')} · ${esc(event.type)}</div><h3 class="mt8">${tr('A turn in the story','故事的转折')}</h3><p>${tx(event.description)}</p><p class="small muted">${tr('This outcome is saved. Refreshing will not reroll it.','结果已保存，刷新不会重选。')}</p><div class="flex wrap mt12">${event.choices.map(q=>button(eventLabel(q),`event:${event.id}:${q}`,'light smallbtn')).join('')}</div></section>`:''}
<section class="card mt"><div class="flex between"><h3>${tr('Inside this chapter’s budget','本章预算明细')}</h3>${!cur?`<button class="textbtn" data-action="costs">${tr('Edit quotations','编辑报价')}</button>`:badge(tr('Snapshot saved','已保存快照'),'neutral')}</div>${budgetList(cur?.items||E.budgetItems(s))}${s.story==='car'?`<p class="small muted mt12">${tr('Ownership rehearsal uses the full monthly cost less genuinely replaced transport. See Finance for every provision and future liability.','拥车演练使用完整月费，扣除真正替代的交通开支。完整准备金及未来责任见财务。')}</p><button class="textbtn mt8" data-action="carfinance">${tr('Explore the ownership calculator','查看拥车计算器')}</button>`:''}${s.story==='travel'?`<div class="mt">${scheduleTable(s)}</div>`:''}<p class="tiny muted mt12">${tr('All seeded prices are illustrative assumptions, independently set for each country. Your quotation takes priority. Historical snapshots stay unchanged.','所有预置价格均为各国独立设定的模拟假设。你的报价优先采用，历史快照不会改写。')}</p></section>${history(s)}</div><aside class="stack" style="align-content:start"><section class="card timeline"><div class="eyebrow muted">${tr('YOUR CHAPTERS','你的章节')}</div><ol>${chapters.map((ch,i)=>`<li class="${i<s.index?'done':i===s.index?'now':''}">${i>s.index?icon('lock').replace('class="icon','style="width:13px;height:13px;vertical-align:-2px;margin-right:4px" class="icon'):''}${i>s.index?tr(`Chapter ${i+1} · not yet revealed`,`第${i+1}章 · 尚未揭晓`):tx(ch.title)}<small>${i<s.index?tr('A memory in your journal','日记中的回忆'):i===s.index?tr('You are here','你在这里'):tx(ACTS[ch.act])}</small></li>`).join('')}</ol></section><section class="notice"><strong>${tr('Your future can change.','未来可以改变。')}</strong><p class="small mt8">${tr('Choose a simpler option or revise future quotations. A game should never come before essential expenses.','可以选择简单方案，或修改未来报价。游戏不能优先于必要开支。')}</p></section></aside></div>`;}
function eventLabel(q){return ({repair:tr('Review repair quote','审阅维修报价'),compare:tr('Compare another provider','比较其他供应商'),review:tr('Review coverage','审阅保障'),buffer:tr('Use virtual contingency','使用虚拟缓冲预算'),indoor:tr('Choose a free indoor day','选择免费室内活动'),reuse:tr('Check and reuse','检查后复用'),new:tr('Keep new essentials','保留新购必需品')})[q]||esc(q);}
function history(s){if(!s.history.length)return '';return `<details class="mt"><summary>${tr('Pages already written','已经写下的篇章')} · ${s.history.length}</summary>${s.history.map(h=>`<div class="cost-row"><div><strong>${tx(h.title)}</strong><small>${tx(h.choice.title)} · ${tr('Cost snapshot','成本快照')} ${cash(h.simulatedCost,s.currency)}<br>${tr('Financial profile','财务档案')} ${esc(h.profileId.slice(0,8))} · ${date(h.completed)}</small></div><span>${cash(h.target,s.currency)}<small>${tr('checkpoint','储蓄目标')}</small></span></div>`).join('')}</details>`;}
function budgetList(items){return items.length?`<div class="cost-list">${items.map(i=>`<div class="cost-row"><div>${tx(i.label)}${i.quantity!==1?` × ${i.quantity}`:''}<small>${i.quote!==null?tr('Your quotation','你的报价'):tr('Illustrative estimate','模拟估计')} · ${i.currency} · ${i.expectedPaymentDate?date(i.expectedPaymentDate):''}</small></div><strong>${cash((i.quote??i.typical)*i.quantity,i.currency)}</strong></div>`).join('')}<div class="cost-row"><strong>${tr('Simulated subtotal','模拟小计')}</strong><strong>${cash(E.itemTotal(items),items[0].currency)}</strong></div></div>`:`<p class="small muted mt12">${tr('No separate item payment in this scene. Rehearsal and future obligations may still apply.','本场景没有独立项目付款。演练和未来责任仍可能适用。')}</p>`;}
function scheduleTable(s){const rows=E.travelSchedule(s);return `<h3>${tr('Save for the booking, not just departure','按预订期限储蓄')}</h3><div class="table-wrap mt12"><table><thead><tr><th>${tr('Deadline','期限')}</th><th>${tr('Cumulative budget','累计预算')}</th><th>${tr('Average daily need','平均每日所需')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${date(r.date)}<br><small class="muted">${tx(r.title)}</small></td><td>${cash(r.cumulative,s.currency)}</td><td>${cash(r.daily,s.currency)}</td></tr>`).join('')}</tbody></table></div><p class="tiny muted mt12">${tr('Daily amounts show cumulative need less your existing trip savings divided by days from story start. Do not add these rates together. Check each early deadline against capacity.','每日金额为累计所需减去已有旅行储蓄，再除以距故事开始的天数。请勿将这些每日数额相加。逐项检查提前期限是否在能力范围内。')}</p>`;}
function financePage(){const p=profile();return header(tr('ROOM TO BREATHE','留些余地'),tr('Give your plans a little perspective.','为计划添一点远见。'),tr('Real numbers for your everyday. A rehearsal for what comes next.','用真实数字看日常，为下一步做演练。'),badge(tr('Real life','真实生活')))+`<div class="tabs"><button data-action="financeview:profile" class="${financeView==='profile'?'active':''}">${tr('My everyday','我的日常')}</button><button data-action="financeview:car" class="${financeView==='car'?'active':''}">${tr('Car rehearsal','拥车演练')}</button><button data-action="financeview:property" class="${financeView==='property'?'active':''}">${tr('Home calculator','住房计算器')}</button></div>`+(!p?`<section class="card empty">${icon('finance')}<h3>${tr('Let’s start with your everyday.','从你的日常开始。')}</h3><p>${tr('Set up your financial profile before planning a future commitment.','规划未来责任前，先建立你的财务档案。')}</p><div class="mt">${button(tr('Set up my profile','建立我的档案'),'onboard')}</div></section>`:financeView==='car'?carCalculator():financeView==='property'?propertyCalculator():financialOverview(p));}
function financialOverview(p){const c=E.capacity(p),expenses=[['Fixed commitments','固定责任',p.fixed,'#879d79'],['Essential living','必要生活',p.living,'#a8c4d2'],['Optional buffer','可选开支缓冲',p.discretionary,'#ce987f'],['Loan repayments','已有贷款供款',p.loans,'#d9c790'],['Emergency contribution','应急供款',p.emergency,'#a5b792']];const s=active(),monthly=s?.current?.target||0;return `<div class="grid3"><section class="card"><div class="eyebrow muted">${tr('MONTHLY NET INCOME','每月净收入')}</div><div class="metric">${cash(c.income)}</div><p class="small muted mt8">${p.incomeCurrency!==p.currency?`${cash(p.income,p.incomeCurrency)} · 1 SGD = ${p.fx} MYR<br>${tr('Your FX assumption dated','你的汇率假设日期')} ${date(p.fxDate)}`:tr('Entered by you. No simulated salary changes.','由你输入。没有模拟薪资变化。')}</p></section><section class="card"><div class="eyebrow muted">${tr('ROOM FOR YOUR MAIN STORY','主线故事可用储蓄')}</div><div class="metric">${cash(c.available)}<small> / ${tr('month','月')}</small></div><p class="small muted mt8">${tr('After essentials, obligations, and the emergency contribution.','已扣除必需开支、责任与应急供款。')}</p></section><section class="card"><div class="eyebrow muted">${tr('YOUR CURRENT BASELINE','你的当前基准')}</div><div class="metric">${date(p.effective)}</div><p class="small muted mt8">${tr(`Financial profile version ${state.versions.indexOf(p)+1}. Historical chapters keep their original version.`,`财务档案第${state.versions.indexOf(p)+1}版。历史章节保留原有版本。`)}</p></section></div>${c.raw<0?`<div class="mt">${notice(tr(`Your budget is short by ${cash(-c.raw)} a month. Pause optional story savings, lower a future target, or extend preparation. Protect essentials and necessary care.`,`你的预算每月短缺${cash(-c.raw)}。请暂停可选故事储蓄、降低未来目标或延长准备期。保障必需开支及必要照护。`),'warn')}</div>`:''}
<div class="grid2 mt"><section class="card"><div class="flex between"><h3>${tr('Where your month goes','每月资金去向')}</h3><button class="textbtn" data-action="editprofile">${tr('Update profile','更新档案')}</button></div><div class="budget-bar">${expenses.map(([,,,color],i)=>`<span style="width:${Math.max(0,expenses[i][2]/Math.max(c.income,1)*100)}%;background:${color}"></span>`).join('')}</div><div class="cost-list">${expenses.map(([en,zh,v,color])=>`<div class="cost-row"><span><i style="display:inline-block;background:${color};width:9px;height:9px;border-radius:3px;margin-right:9px"></i>${tr(en,zh)}</span><strong>${cash(v)}</strong></div>`).join('')}<div class="cost-row"><strong>${tr('Main story savings capacity','主线储蓄能力')}</strong><strong>${cash(c.available)}</strong></div></div><p class="tiny muted mt12">${tr('Put each expense in one category only. Loan repayments belong in obligations, not again in fixed commitments. Transport already included in living costs can be offset in the car simulator.','每笔开支只放入一个类别。贷款供款属于债务责任，不应再次计入固定责任。已包含在生活费的交通开支可在拥车模拟中抵扣。')}</p></section><section class="card"><h3>${tr('A look at the months ahead','看看未来几个月')}</h3><p class="small muted mt12">${tr('A projection from your current profile, not a prediction of income. Story prices stay simulated.','基于当前档案的预测，并非收入预测。故事价格保持为模拟。')}</p><div class="table-wrap mt12"><table><thead><tr><th>${tr('Month','月份')}</th><th>${tr('Main capacity','主线能力')}</th><th>${tr('Emergency plan','应急计划')}</th></tr></thead><tbody>${[1,2,3,4,5,6].map(i=>{const future=E.addDays(E.today(),i*30),fp=E.activeProfile(state,future)||p;return `<tr><td>${date(future)}</td><td>${cash(E.capacity(fp).available,fp.currency)}</td><td>${cash(fp.emergency,fp.currency)}</td></tr>`;}).join('')}</tbody></table></div><p class="tiny muted mt12">${tr('Future-dated profile versions apply only from their effective dates.','未来生效的档案版本仅从生效日期开始应用。')}</p></section></div>
<details><summary>${tr('Financial profile history','财务档案历史')} · ${state.versions.length}</summary>${state.versions.map(v=>`<div class="cost-row"><div>${date(v.effective)} ${v.effective>E.today()?badge(tr('Scheduled','已安排'),'yellow'):''}<small>${tr('Monthly income','月收入')} ${cash(v.income,v.incomeCurrency)} · ${tr('Residence','居住地')} ${v.country}</small></div><span class="tiny muted">${esc(v.id.slice(0,8))}</span></div>`).join('')}</details><details><summary>${tr('Pricing assumptions & source notes','价格假设与资料说明')}</summary><p>${tr('Every prefilled price is an illustrative V1 assumption, last prepared 25 November 2026. No seeded price is represented as a verified provider quotation. Sources below inform calculation and care context only.','所有预填价格都是V1模拟假设，编制于2026年11月25日。没有任何预置价格被称为已核实的供应商报价。以下资料仅用于计算及照护背景。')}</p>${SOURCES.map(s=>`<p><a href="${s.url}" target="_blank" rel="noreferrer">${esc(s.name)}</a><br><span class="muted">${tx(s.note)}</span></p>`).join('')}</details>`;}
const carLabels={price:L('Vehicle price incl. applicable taxes / COE','车价（含适用税费／COE）'),down:L('Down payment','首付'),years:L('Loan years','贷款年数'),rate:L('Annual quoted rate (%)','年报价利率（%）'),age:L('Vehicle age (years)','车龄（年）'),mileage:L('Monthly mileage (km)','每月里程（公里）'),consumption:L('Litres / kWh per 100 km','每100公里升数／千瓦时'),unitPrice:L('Fuel / charging unit price','燃油／充电单价'),insurance:L('Annual insurance quotation','年度保险报价'),tax:L('Annual road tax quotation','年度路税报价'),parking:L('Monthly parking','每月停车费'),tolls:L('Monthly tolls','每月过路费'),maintenance:L('Monthly maintenance provision','每月保养准备金'),tyres:L('Monthly tyres provision','每月轮胎准备金'),battery:L('Monthly battery provision','每月电池准备金'),repairs:L('Monthly repair reserve','每月维修准备金'),replacedTransport:L('Existing transport genuinely replaced / month','每月真正替代的已有交通费'),omv:L('Open Market Value (SGD)','公开市场价值（SGD）'),coeYears:L('Remaining COE years','COE剩余年数')};
const carLineLabels={instalment:L('Loan instalment','贷款供款'),energy:L('Fuel / charging','燃油／充电'),insurance:L('Insurance provision','保险准备金'),roadTax:L('Road tax provision','路税准备金'),parking:L('Parking','停车'),tolls:L('Tolls','过路费'),maintenance:L('Maintenance','保养'),tyres:L('Tyres provision','轮胎准备金'),battery:L('Battery provision','电池准备金'),repairs:L('Repair reserve','维修准备金')};
let carDraft=null,propertyDraft=null;
function carCalculator(){const p=profile(),s=active();if(!carDraft||carDraft.country!==p.country)carDraft={...(s?.story==='car'&&s.country===p.country?s.config:carDefaults(p.country)),country:p.country};const c=carDraft;return `<div class="grid2"><section class="card"><div class="flex between"><h3>${tr('The car you have in mind','你心里的那辆车')}</h3>${badge(p.country==='SG'?'Singapore · SGD':'Malaysia · MYR','blue')}</div><p class="small muted mt12">${tr('Editable assumptions. Compare the whole responsibility before making a commitment.','可编辑的假设。做决定前，比较完整责任。')}</p><form id="car-form" class="mt"><div class="form-grid">${['price','down','years','rate'].map(k=>field(tx(carLabels[k]),k,c[k],'number','',k==='years'?'max="15" min="1"':'')).join('')}${select(tr('Calculation method','计算方式'),'method',c.method,[['flat',tr('Flat rate','平息')],['reducing',tr('Reducing balance','递减余额')]])}${select(tr('Vehicle condition','车辆状况'),'condition',c.condition,[['new',tr('New','新车')],['used',tr('Used','二手车')]])}${field(tx(carLabels.age),'age',c.age)}${select(tr('Fuel type','能源类型'),'fuel',c.fuel,[['petrol',tr('Petrol','汽油')],['diesel',tr('Diesel','柴油')],['electric',tr('Electric','电动')],['hybrid',tr('Hybrid','混合动力')]])}${['mileage','consumption','unitPrice','replacedTransport','insurance','tax','parking','tolls','maintenance','tyres','battery','repairs',...(p.country==='SG'?['omv','coeYears']:[])].map(k=>field(tx(carLabels[k]),k,c[k])).join('')}${select(tr('Simulated coverage','模拟保障'),'coverage',c.coverage,[['comprehensive',tr('Comprehensive (policy-specific)','综合保障（依保单）')],['thirdParty',tr('Third party','第三者')]])}<label class="check"><input type="checkbox" name="warranty" ${c.warranty?'checked':''}>${tr('An applicable simulated warranty covers this mechanical defect','适用的模拟保修涵盖此机械故障')}</label></div>${formError}<div class="form-actions"><button type="submit" class="btn">${tr('Recalculate','重新计算')}</button></div></form></section><div class="stack" style="align-content:start"><section class="card" id="car-result">${carResult(c,p)}</section>${notice(tr('Financing is a simulation, not an offer or eligibility decision. A flat quoted rate and an effective annual rate are different. Replace tax, insurance and fuel assumptions with quotations.','融资仅为模拟，并非报价或资格决定。平息报价利率与实际年利率不同。请使用真实税费、保险及燃油报价。'),'blue')}</div></div>`;}
function carResult(c,p){const cost=E.carCosts(c),cap=E.capacity(p).available,short=Math.max(0,cost.additional-cap);const sgInvalid=p.country==='SG'&&(c.years>7||(c.price-c.down)>c.price*(c.omv>20000?.6:.7)+.01||c.years>c.coeYears);return `<div style="height:140px;display:grid;place-items:center;background:#e8eff0;border-radius:12px">${miniArt('car')}</div><div class="eyebrow muted mt">${tr('THE FULL MONTHLY PICTURE','完整的每月成本')}</div><div class="metric">${cash(cost.ownership,p.currency)}<small> / ${tr('month','月')}</small></div><div class="cost-list mt12">${cost.lines.map(([key,v])=>`<div class="cost-row"><span>${tx(carLineLabels[key])}</span><strong>${cash(v,p.currency)}</strong></div>`).join('')}<div class="cost-row"><span>${tr('Less replaced transport','减去被替代的交通费')}</span><strong>− ${cash(Math.min(cost.ownership,c.replacedTransport),p.currency)}</strong></div><div class="cost-row"><strong>${tr('Additional monthly burden','每月新增负担')}</strong><strong>${cash(cost.additional,p.currency)}</strong></div></div><div class="mt12">${notice(short?tr(`${cash(short,p.currency)} monthly shortfall. A reduced savings challenge does not prove you can afford this vehicle.`,`每月短缺${cash(short,p.currency)}。完成较低储蓄目标不能证明能负担此车辆。`):tr('Within the capacity you entered. Allow for uncertainty and obtain real quotations before committing.','在你输入的能力范围内。做决定前仍需考虑不确定性并取得真实报价。'),short?'warn':'')}</div>${sgInvalid?`<div class="mt12">${notice(tr('Singapore financing assumptions need review: model a maximum 7-year term, applicable 60% / 70% LTV based on OMV, and remaining COE. Lender eligibility and used-vehicle tenure can be stricter.','新加坡融资假设需要审阅：模拟最长7年、按OMV适用60%／70%融资比例，并考虑COE剩余年限。贷款资格及二手车年限可能更严格。'),'warn')}</div>`:''}<div class="cost-row mt12"><span>${tr('Upfront: down payment + first-year insurance & tax','前期：首付＋首年保险及税费')}</span><strong>${cash(cost.upfront,p.currency)}</strong></div><div class="cost-row"><span>${tr('Total contractual loan interest','合同贷款利息总额')}</span><strong>${cash(cost.interest,p.currency)}</strong></div><div class="cost-row"><span>${tr('Virtual value after 24 months (illustrative depreciation)','24个月后虚拟价值（模拟折旧）')}</span><strong>${cash(E.virtualCarValue(c,24).value,p.currency)}</strong></div><p class="tiny muted mt8">${tr('Value uses a model assumption of 15% annual depreciation for new cars and 10% for used cars. It is not a resale quotation and does not change the loan.','价值按新车每年15%、二手车10%的模拟折旧假设计。并非二手报价，不会改变贷款。')}</p><div class="cost-row"><span>${tr('Remaining principal after 24 loan payments','24次供款后剩余本金')}</span><strong>${cash(E.remainingLoan(c,24).principal,p.currency)}</strong></div><p class="tiny muted mt12">${tr('Annual provisions build for the next renewal; renewal is not added again to monthly ownership cost. Upfront first-year premiums are separate from next-year provisions.','年度准备金用于下次续保，不会再次加到每月拥车成本。首年前期保费与下一年度准备金分开。')}</p><div class="mt">${button(tr('Use for my car story','用于我的拥车故事'),'applycar','secondary')}</div><p class="small muted mt12">${tr('Consider a cheaper vehicle, a larger down payment from available funds, revised financing assumptions, more preparation time, or postponing.','可考虑较便宜车辆、使用可用资金提高首付、修改融资假设、延长准备期或推迟。')}</p>`;}
function propertyCalculator(){const p=profile();if(!propertyDraft||propertyDraft.country!==p.country)propertyDraft=p.country==='SG'?{country:'SG',type:'hdb',condition:'new',price:650000,down:162500,years:25,rate:3,legal:3000,duty:15000,valuation:500,renovation:40000,furniture:12000,fees:300,tax:150,insurance:40,maintenance:150,utilities:250,moving:1000}:{country:'MY',type:'private',condition:'subsale',price:450000,down:45000,years:30,rate:4.2,legal:6000,duty:10000,valuation:1500,renovation:20000,furniture:12000,fees:250,tax:75,insurance:50,maintenance:150,utilities:250,moving:1000};const c=propertyDraft;const labels={price:L('Property price','房价'),down:L('Down payment','首付'),years:L('Loan term (years)','贷款年限'),rate:L('Annual reducing rate (%)','递减年利率（%）'),legal:L('Legal fees quotation','律师费报价'),duty:L('Applicable duties quotation','适用印花税报价'),valuation:L('Valuation & financing fees','估价与融资费用'),renovation:L('Repairs & renovation budget','维修与装修预算'),furniture:L('Furniture & appliances','家具与电器'),fees:L('Monthly management fees','每月管理费'),tax:L('Monthly tax provision','每月税费准备金'),insurance:L('Monthly insurance provision','每月保险准备金'),maintenance:L('Monthly maintenance reserve','每月维护准备金'),utilities:L('Monthly utilities','每月水电费用'),moving:L('Moving expenses','搬家费用')};const l=E.loan(c.price-c.down,c.rate,c.years),monthly=l.monthly+c.fees+c.tax+c.insurance+c.maintenance+c.utilities,upfront=c.down+c.legal+c.duty+c.valuation+c.renovation+c.furniture+c.moving;return `<div class="grid2"><section class="card"><h3>${tr('A place called home','一个叫家的地方')}</h3><form id="property-form" class="mt"><div class="form-grid">${select(tr('Property type','房产类型'),'type',c.type,p.country==='SG'?[['hdb','HDB'],['private',tr('Private property','私人住宅')]]:[['private',tr('Private property','私人住宅')]])}${select(tr('Purchase flow','购买流程'),'condition',c.condition,[['new',tr('New build','新房')],['subsale',tr('Subsale','二手房')]])}${Object.keys(labels).map(k=>field(tx(labels[k]),k,c[k])).join('')}</div>${formError}<div class="form-actions"><button type="submit" class="btn">${tr('Explore these numbers','看看这些数字')}</button></div></form></section><div class="stack" style="align-content:start"><section class="card"><div class="story-preview-art">${miniArt('home')}</div><div class="eyebrow muted">${tr('ESTIMATED UPFRONT BUDGET','估计前期预算')}</div><div class="metric">${cash(upfront)}</div><hr class="rule"><div class="eyebrow muted">${tr('MONTHLY ONGOING RESPONSIBILITY','每月持续责任')}</div><div class="metric">${cash(monthly)}<small> / ${tr('month','月')}</small></div><div class="cost-row"><span>${tr('Loan instalment included','其中贷款供款')}</span><strong>${cash(l.monthly)}</strong></div><p class="small muted mt12">${tr('The loan is modelled at a constant reducing rate. Floating rates, transaction duties, grants, taxes, eligibility and financing rules require current individual checks. No qualification is assumed.','贷款按固定递减利率模拟。浮动利率、交易税费、补助、税务、资格及融资规则需要按最新个人情况确认。此处不假定你符合资格。')}</p></section>${notice(p.country==='SG'?tr('Singapore: HDB has its own eligibility and application process; private property follows a different purchase route. CPF use, grants, buyer duties and financing limits are not automatically calculated. Enter a current individual quotation.','新加坡：HDB有独立资格和申请程序，私人住宅的购买流程不同。CPF使用、补助、买方印花税与融资限制不会自动计算。请输入最新个人报价。'):tr('Malaysia: budget for financing review, sale agreements, legal work, applicable duties, valuation and transaction-specific fees. Enter a current local quotation.','马来西亚：请为融资审阅、买卖协议、法律程序、适用印花税、估价及交易费用作预算。请输入最新本地报价。'),'blue')}<section class="card"><h3>${tr('Your purchase route','你的购房路线')}</h3><p class="small muted mt12">${c.condition==='new'?tr('Research → showroom → affordability & financing → legal review → construction / handover → defect inspection → renovation → furniture & move-in.','研究 → 展厅 → 负担能力与融资 → 法律审阅 → 施工／交付 → 缺陷检查 → 装修 → 家具与入住。'):tr('Search → view & inspect → ownership review → financing → negotiate → legal completion → keys → repairs / renovation → furniture & move-in.','寻找 → 看房与检查 → 产权审阅 → 融资 → 协商 → 法律手续 → 交钥匙 → 维修／装修 → 家具与入住。')}</p><div class="mt12">${badge(tr('Story in development · calculator available','故事开发中 · 计算器可用'),'yellow')}</div></section></div></div>`;}
function savingsPage(){const p=profile(),s=active();if(!p)return header('',tr('Small steps, saved for something good.','小小积累，存向美好。'),tr('Build a financial profile to begin your savings journal.','建立财务档案，开始储蓄日记。'))+`<section class="card empty">${miniArt('plant')}<div class="mt">${button(tr('Begin my journal','开始我的日记'),'onboard')}</div></section>`;const saved=s?E.allocation(state,s.id,s.currency):0,target=s?.current?.requiredTotal||0,res=E.reserves(state,p),goal=(p.fixed+p.living+p.loans)*state.emergency.months;return `${header(tr('YOUR LITTLE ACTS OF PROGRESS','你的小小进步'),tr('A little today. A little closer.','今天存一点，梦想近一点。'),tr('Transfer to your own account. Record it here when you’re ready.','转入你自己的账户，准备好后在此记录。'),button(icon('plus')+tr('Record savings','记录储蓄'),'deposit'))}<div class="grid2"><section class="card saving-card"><div class="eyebrow">${tr('MY STORY CONTRIBUTIONS','我的故事储蓄')}</div><h3>${cash(saved,s?.currency||p.currency)}</h3><p>${s?tx(story(s.story).title):tr('Choose a main story to begin','选择主线故事即可开始')}</p>${progress(saved,target||Math.max(1000,saved))}<div class="flex between mt12 small"><span>${tr('Self-confirmed, local demo','自行确认 · 本地演示')}</span><span>${target?cash(target,s.currency):'—'}</span></div><button class="textbtn" data-action="nav:story">${tr('Visit this chapter','查看本章')}</button></section><section class="card"><div class="flex between"><h3>${tr('Your safety net','你的安全网')}</h3><button class="textbtn" data-action="emergency">${tr('Adjust plan','调整计划')}</button></div><div class="metric">${cash(res)} <small>/ ${cash(goal)}</small></div><div class="mt12">${progress(res,goal)}</div><p class="small muted mt12">${state.emergency.enabled?tr(`${cash(p.emergency)} planned per month · ${state.emergency.months} months of core expenses.`,`每月计划${cash(p.emergency)} · ${state.emergency.months}个月的核心开支。`):tr('An optional plan you can grow alongside your main story.','一项可与主线故事并行的可选计划。')}</p><p class="tiny muted mt8">${tr('An emergency goal does not block your main story. Simulated emergencies never withdraw this balance.','应急目标不会阻止主线故事。模拟意外不会扣减此余额。')}</p></section></div>
<div class="mt">${notice(tr('Local demo evidence review: uploads and references are checked for duplicates, then you explicitly self-confirm the record. This is not bank verification. Pending or rejected evidence does not count. Save Your Story never receives, holds or transfers money.','本地演示凭证审阅：上传文件及参考号会进行重复检查，然后由你明确确认记录。这不是银行验证。待审或已拒绝凭证不计入进度。Save Your Story不会接收、保管或转移资金。'),'blue')}</div>
${s?.story==='travel'?`<section class="card mt">${scheduleTable(s)}<p class="small muted mt12">${tr('Group several daily or weekly transfers in one evidence submission. Use a unique batch reference and allocate only the total actually transferred.','可将多个每日或每周转账合并为一次凭证提交。使用唯一批次参考号，只分配真实已转账总额。')}</p></section>`:''}
<div class="section-head"><h2>${tr('Your savings journal','你的储蓄日记')}</h2><span class="small muted">${state.ledger.length} ${tr('records','条记录')}</span></div><div class="receipt-list">${state.ledger.length?state.ledger.slice().reverse().map(t=>`<section class="receipt"><div class="flex between wrap"><div><h4>${esc(t.reference)}</h4><p class="small muted mt8">${date(t.date)} · ${t.fileName?esc(t.fileName):tr('Manually recorded','手动记录')}</p></div><div class="right"><strong>${cash(t.amount,t.currency)}</strong><div class="mt8">${badge(t.status==='confirmed'?tr('Self-confirmed · demo','自行确认 · 演示'):t.status==='pending'?tr('Awaiting your review','等待你审阅'):tr('Rejected','已拒绝'),t.status==='pending'?'yellow':t.status==='rejected'?'rose':'')}</div></div></div><p class="small muted mt12">${tr('Story','故事')} ${cash(t.main,t.currency)} · ${tr('Emergency','应急')} ${cash(t.emergency,t.currency)} · ${tr('Unallocated','未分配')} ${cash(t.amount-t.main-t.emergency,t.currency)}</p><div class="flex wrap mt12">${t.status==='pending'?button(tr('Review evidence','审阅凭证'),`review:${t.id}`,'secondary smallbtn'):''}${t.fileName?`<button class="textbtn" data-action="evidence:${t.id}">${tr('View local evidence','查看本地凭证')}</button>`:''}</div></section>`).join(''):`<section class="empty">${icon('leaf')}<h3>${tr('Every habit starts with one small step.','每个习惯，始于小小一步。')}</h3><p class="small">${tr('Your first recorded contribution will appear here.','你的第一笔储蓄记录会显示在这里。')}</p></section>`}</div>`;}
function profilePage(){const p=profile();return `${header(tr('MAKE IT YOURS','由你做主'),tr('Your story. Your settings.','你的故事，你的设定。'),tr('A quiet place to care for the details.','安静地打理生活细节。'))}<div class="grid2"><section class="card"><div class="flex"><div class="avatar" style="width:60px;height:60px;font-size:1.6rem">${esc(state.name[0]||'A')}</div><div><h3>${esc(state.name)}</h3><p class="small muted">${tr('Local demo · saved on this browser','本地演示 · 保存在此浏览器')}</p></div></div><div class="settings-row"><div><p>${tr('Your name','你的名字')}</p><small>${tr('How your journal greets you','日记如何称呼你')}</small></div><button class="textbtn" data-action="name">${tr('Edit','编辑')}</button></div><div class="settings-row"><div><p>${tr('Language','语言')}</p><small>${state.language==='en'?'English':'简体中文'}</small></div><button class="textbtn" data-action="language">${tr('Switch to 中文','切换为 English')}</button></div><div class="settings-row"><div><p>${tr('Country & income currency','国家与收入币种')}</p><small>${p?`${p.country==='MY'?tr('Malaysia','马来西亚'):tr('Singapore','新加坡')} · ${p.incomeCurrency} ${tr('income','收入')} / ${p.currency} ${tr('expenses','支出')}`:tr('Not configured yet','尚未设定')}</small></div><button class="textbtn" data-action="${p?'editprofile':'onboard'}">${tr('Configure','设定')}</button></div><div class="settings-row"><div><p>${tr('In-app reminders','应用内提醒')}</p><small>${tr('Show Savings Day reminders when you open the app. No background notifications.','打开应用时显示储蓄日提醒，无后台通知。')}</small></div><input class="toggle" type="checkbox" id="notifications" aria-label="${tr('In-app reminders','应用内提醒')}" ${state.notifications?'checked':''}></div><div class="settings-row"><div><p>${tr('Financial profile','财务档案')}</p><small>${tr('Assets, reserves and actual monthly obligations','资产、储备及真实每月责任')}</small></div><button class="textbtn" data-action="${p?'editprofile':'onboard'}">${tr('Manage','管理')}</button></div></section><div class="stack" style="align-content:start"><section class="card"><h3>${tr('Pages you’ve made your own','属于你的篇章')}</h3><div class="grid2 mt"><div><div class="metric">${state.sessions.reduce((n,s)=>n+s.history.length,0)}</div><p class="small muted">${tr('Chapters completed','完成章节')}</p></div><div><div class="metric">${state.sessions.filter(s=>s.completed).length}</div><p class="small muted">${tr('Stories completed','完成故事')}</p></div></div><p class="small muted mt">${tr('Achievements celebrate your choices and recorded savings. They never change your real finances.','成就庆祝你的选择和储蓄记录，不会改变真实财务。')}</p></section><section class="card"><h3>${tr('Your data belongs to you','你的数据，属于你')}</h3><p class="small muted mt12">${tr('Financial profiles and decisions stay in browser storage. Evidence files stay in local IndexedDB. There is no bank connection, server review, cross-device sync or background upload. Device storage can be cleared by your browser.','财务档案与选择保存在浏览器，凭证文件保存在本地IndexedDB。没有银行连接、服务端审阅、跨设备同步或后台上传。浏览器可能清除设备储存。')}</p><div class="flex wrap mt">${button(icon('download')+tr('Export backup','导出备份'),'export','secondary smallbtn')}${button(tr('Restore backup','恢复备份'),'import','light smallbtn')}</div><p class="tiny muted mt12">${tr('JSON backups include finances and progress, but exclude receipt files. Keep backups private.','JSON备份包含财务与进度，不包含凭证文件。请妥善保管。')}</p><hr class="rule"><button class="textbtn" data-action="reset" style="color:#985943">${tr('Delete all local data','删除所有本地数据')}</button></section></div></div>${state.sessions.length?`<details><summary>${tr('Story archive','故事档案')}</summary>${state.sessions.map(s=>`<div class="cost-row"><span>${tx(story(s.story).title)}<small>${date(s.created)} · ${s.currency} · ${s.history.length} ${tr('chapters completed','章已完成')}</small></span>${badge(s.completed?tr('Completed','已完成'):tr('Active','进行中'))}</div>`).join('')}</details>`:''}`;}
function defaultProfile(){return {name:state.name,country:'MY',currency:'MYR',incomeCurrency:'MYR',income:0,fixed:0,living:0,discretionary:0,loans:0,savings:0,reserves:0,emergency:0,loanBalance:0,assets:0,fx:3.3,fxDate:E.today(),effective:E.today()};}
function onboarding(){const d=formDraft;const steps=`<div class="steps" aria-label="${tr('Setup progress','设定进度')}">${[0,1,2,3].map(i=>`<span class="${i<=onboardStep?'done':''}"></span>`).join('')}</div>`;const welcome=`<div class="story-preview-art">${miniArt('plant')}</div><h3>${tr('Play your future. Keep your money.','体验未来，保管好你的钱。')}</h3><p class="small muted mt12">${tr('Explore a local demo. Your story decisions are simulated. Only the amounts you enter or explicitly confirm affect your real financial journal.','体验本地演示。故事选择均为模拟。只有你输入或明确确认的金额，才会影响真实财务日记。')}</p><div class="form-grid mt">${field(tr('What should we call you?','我们该如何称呼你？'),'name',d.name,'text','','required maxlength="40"')}${select(tr('Language','语言'),'language',state.language,[['en','English'],['zh','简体中文']])}${select(tr('Country of residence','居住国家'),'country',d.country,[['MY',tr('Malaysia','马来西亚')],['SG',tr('Singapore','新加坡')]])}${select(tr('Income currency','收入币种'),'incomeCurrency',d.incomeCurrency,[['MYR','MYR · RM'],['SGD','SGD · S$']])}${field(tr('MYR per 1 SGD (your assumption)','每1 SGD的MYR（你的假设）'),'fx',d.fx,'number',tr('Editable assumption, not a live exchange rate.','可编辑假设，并非实时汇率。'),'min="0.0001" step="0.0001" required')}${field(tr('Exchange-rate date','汇率日期'),'fxDate',d.fxDate,'date','','required')}</div>`;
const finances=`<h3>${tr('A picture of your everyday','你的日常收支')}</h3><p class="small muted mt12">${tr(`Income is in ${d.incomeCurrency}. All other amounts are in ${d.country==='MY'?'MYR':'SGD'}. Enter each expense once.`,`收入使用${d.incomeCurrency}，其他金额使用${d.country==='MY'?'MYR':'SGD'}。每笔开支只记录一次。`)}</p><button type="button" class="textbtn mt8" data-action="sample">${tr('Use clearly labelled sample amounts','使用已标明的示例金额')}</button><div class="form-grid mt">${profileFields(d)}</div>`;
const cap=E.capacity({...d,currency:d.country==='MY'?'MYR':'SGD'});const review=`<div class="story-preview-art">${miniArt('book')}</div><h3>${tr('A little room for your story','为故事留些空间')}</h3><div class="metric">${cash(cap.available,d.country==='MY'?'MYR':'SGD')}<small> / ${tr('month','月')}</small></div><p class="small muted mt12">${tr('Your main story capacity, after your planned emergency contribution. An optional emergency plan can run alongside one main story.','这是扣除应急供款后的主线故事能力。可选应急计划可以与一个主线故事并行。')}</p><div class="mt">${notice(cap.raw<0?tr('Your everyday budget has a shortfall. Explore simpler plans, extend preparation, or postpone a commitment. Protect your essentials.','你的日常预算存在短缺。可探索简单方案、延长准备期或推迟。请保障必需开支。'):tr('A savings challenge will always show when your goal exceeds current capacity. A smaller checkpoint is not proof of affordability.','当目标超出当前能力时，储蓄挑战会明确提示。较小的目标不代表能负担该计划。'),cap.raw<0?'warn':'')}</div><label class="check mt"><input type="checkbox" name="ack" required>${tr('I understand that this is a local demo, estimates are illustrative, and my funds stay in my own account.','我理解这是本地演示，估计金额仅为模拟，资金保留在自己的账户。')}</label>`;
openModal(tr('A new story begins','新的故事开始了'),`${steps}<form id="onboard-form">${onboardStep===0?welcome:onboardStep===1?finances:review}${formError}<div class="form-actions">${onboardStep>0?button(tr('Back','返回'),'onboardback','secondary','type="button"'):''}<button class="btn" type="submit">${onboardStep<2?tr('A little further','继续一点'):tr('Explore my stories','探索我的故事')}</button></div></form><p class="tiny muted mt12">${tr('Local demo only. No account, bank integration, or money transfer is created.','仅本地演示，不创建账户、银行连接或转账。')}</p>`);}
function profileFields(d){return [field(tr('Monthly net income','每月净收入'),'income',d.income),field(tr('Fixed commitments (exclude loan repayments)','固定责任（不含贷款供款）'),'fixed',d.fixed),field(tr('Essential living expenses','必要生活开支'),'living',d.living),field(tr('Discretionary spending buffer','可选开支缓冲'),'discretionary',d.discretionary),field(tr('Existing monthly loan repayments','已有每月贷款供款'),'loans',d.loans),field(tr('Monthly emergency contribution','每月应急供款'),'emergency',d.emergency),field(tr('Available savings, excluding emergency reserves','可用储蓄，不含应急储备'),'savings',d.savings),field(tr('Separate emergency reserves','独立应急储备'),'reserves',d.reserves),field(tr('Actual outstanding loan principal','真实未偿贷款本金'),'loanBalance',d.loanBalance||0),field(tr('Other actual asset value (optional)','其他真实资产价值（可选）'),'assets',d.assets||0)].join('');}
function editProfile(){const p=profile();formDraft={...p,savings:E.recordedSavings(state,p),reserves:E.reserves(state,p),effective:E.today()};openModal(tr('Update your real-life profile','更新你的真实财务档案'),`<p class="small muted">${tr('Changes create a dated version. Confirm the current total balances, including prior contributions. Earlier story snapshots will not change.','更改会创建带日期的版本。请确认包含之前供款的当前总余额。早先故事快照不会改变。')}</p><form id="profile-form" class="mt"><div class="form-grid">${select(tr('Residence / expense currency','居住地／支出币种'),'country',p.country,[['MY','Malaysia · MYR'],['SG','Singapore · SGD']])}${select(tr('Income currency','收入币种'),'incomeCurrency',p.incomeCurrency,[['MYR','MYR'],['SGD','SGD']])}${field(tr('MYR per 1 SGD','每1 SGD的MYR'),'fx',p.fx,'number','','min="0.0001" required')}${field(tr('Exchange-rate date','汇率日期'),'fxDate',p.fxDate,'date','','required')}${profileFields(formDraft)}<div class="full">${field(tr('Effective date','生效日期'),'effective',E.today(),'date',tr('Cannot predate today. Past records remain unchanged.','不可早于今天。历史记录保持不变。'),`required min="${E.today()}"`)}</div></div>${formError}<div class="form-actions"><button type="submit" class="btn">${tr('Save a new version','保存新版本')}</button></div></form>`);}
function preview(id){previewId=id;const st=story(id),p=profile(),country=p?.country||'MY',cur=country==='MY'?'MYR':'SGD',s=active();if(id==='emergency'&&p){emergencyModal();return;}let form='';if(st.playable&&id!=='emergency'){
if(id==='car'){const c=carDefaults(country);form=`<p class="small muted">${tr('Start with an illustrative car. Every ownership line can be edited in Finance, including mileage, fuel, insurance and repair reserves.','从模拟车辆开始。所有拥车明细都可在财务中编辑，包括里程、能源、保险及维修准备金。')}</p><div class="form-grid mt12">${field(tr('Vehicle price','车价'),'price',c.price)}${field(tr('Down payment','首付'),'down',c.down)}${field(tr('Loan years','贷款年数'),'years',c.years,'number','','min="1" max="15"')}${field(tr('Annual rate (%)','年利率（%）'),'rate',c.rate)}${select(tr('New / used','新车／二手车'),'condition',c.condition,[['new',tr('New','新车')],['used',tr('Used','二手车')]])}${select(tr('Calculation method','计算方式'),'method',c.method,[['flat',tr('Flat rate','平息')],['reducing',tr('Reducing balance','递减余额')]])}</div>`;}
if(id==='travel')form=`<div class="form-grid">${field(tr('Destination','目的地'),'destination','Penang','text','','required maxlength="80"')}${field(tr('Travellers','旅客人数'),'travellers',1,'number','','min="1" max="12" step="1"')}${field(tr('Departure date','出发日期'),'departure',E.addDays(E.today(),100),'date','',`required min="${E.addDays(E.today(),30)}" max="${E.addDays(E.today(),365)}"`)}${field(tr('Trip length (days)','旅行天数'),'travelDays',5,'number','','min="1" max="90" step="1"')}${select(tr('Travel style','旅行风格'),'style','thoughtful',[['simple',tr('Simple','简单')],['thoughtful',tr('Thoughtful','用心')],['comfortable',tr('Comfortable','舒适')]])}${field(tr('Existing trip savings (already set aside)','已预留旅行储蓄'),'existing',0)}${field(tr('Flight payment deadline (days from now)','机票付款期限（距今天数）'),'flightDay',25,'number','','min="1" max="365" step="1"')}${field(tr('Hotel payment deadline (days from now)','住宿付款期限（距今天数）'),'hotelDay',50,'number','','min="1" max="365" step="1"')}</div><details open><summary>${tr('Your custom travel budget','你的自定旅行预算')}</summary><p class="tiny muted">${tr('Accommodation is the total for all nights and travellers. Other lines are per traveller for the whole trip. Prices do not automatically change with destination or trip length. Enter quotations.','住宿为所有晚数和旅客的总额。其他项目为每位旅客全程预算。价格不会随目的地或天数自动改变，请输入报价。')}</p><div class="form-grid mt12">${['flight','hotel','visa','transport','meals','activities','insurance','shopping','buffer'].map(k=>{const i=price(k,country);return field(tx(i.label),`budget_${k}`,i.typical);}).join('')}</div></details>`;
if(id==='baby')form=`<label class="check"><input type="checkbox" name="knownTwins">${tr('I am planning for a known twin pregnancy','我正在为已知双胎怀孕做计划')}</label><p class="small muted mt12">${tr('Otherwise, the confirmation chapter uses a persisted 99% single / 1% twin game roll. This is not a medical statistic. The first scene is buying a pregnancy test kit.','否则，确认章节使用固定保存的99%单胎／1%双胎游戏概率。这不是医学统计。第一个场景是购买验孕工具。')}</p><div class="form-grid mt">${select(tr('Care setting (budget preference)','照护环境（预算偏好）'),'careSetting','mixed',[['public',tr('Public care · enter eligibility-specific quote','公共照护 · 输入适用个人报价')],['mixed',tr('Mixed / undecided','混合／待定')],['private',tr('Private care · enter provider quote','私人照护 · 输入供应商报价')]])}${field(tr('Delivery & hospital total quotation','分娩与住院总报价'),'delivery',price('delivery',country).typical)}${field(tr('Postpartum support total quotation','产后支持总报价'),'postpartum',price('postpartum',country).typical)}${field(tr('Move delivery scene to story month','将分娩场景移至故事月份'),'birthMonth',9,'number',tr('Budget timing only. Individual care comes first.','仅预算时间，个人照护优先。'),'min="7" max="10" step="1"')}</div>`;
}
const locked=s&&!s.completed;openModal(tx(st.title),`<div class="story-preview-art ${st.color}">${miniArt(st.icon)}</div><p class="muted">${tx(st.subtitle)}</p><div class="flex wrap mt12">${badge(tx(st.duration),'neutral')}${badge(st.playable?tr('Playable V1','V1可玩'):tr('In development · preview only','开发中 · 仅预览'),st.playable?'':'yellow')}</div><div class="notice mt"><strong>${tr('Illustrative budget preview','模拟预算预览')}</strong><p class="small mt8">${cash(Math.min(...st.range[country]),cur)} – ${cash(Math.max(...st.range[country]),cur)}${id==='car'?tr(' · sample price / preparation envelope, ongoing costs are extra.',' · 示例车价／准备范围，持续开支另计。'):tr(' · replace with your own local quotations.',' · 请替换为你自己的本地报价。')}</p></div>${!st.playable?`<p class="small muted mt">${tr('This story is not playable yet. The five-act outline and cost planning structure are ready for future development.','此故事尚不可游玩。五幕大纲与成本规划结构已为后续开发准备。')}</p><div class="cost-list mt12">${FUTURE[id].chapters.map((ch,i)=>`<div class="cost-row"><span>${tx(ch.title)}<small>${tx(ch.intro)}</small></span>${icon('lock')}</div>`).join('')}</div>${id==='home'&&p?`<div class="mt">${button(tr('Use the home calculator','使用住房计算器'),'homefinance','secondary')}</div>`:''}`:`<form id="start-form" class="mt">${form}${formError}${locked?`<div class="mt">${notice(tr('Your main story is locked until its final chapter. You can preview other journeys and run an emergency plan alongside it.','主线故事锁定至最后一章。你仍可预览其他旅程，并同时运行应急计划。'),'warn')}</div>`:''}<label class="check mt"><input name="lockack" type="checkbox" required ${locked?'disabled':''}>${tr('I understand this journey’s estimated duration, illustrative costs, and the one-main-story lock.','我了解旅程的估计时长、模拟成本及一个主线故事的锁定规则。')}</label><div class="form-actions"><button type="submit" class="btn" ${locked?'disabled':''}>${p?tr('Start & keep this story','开始并锁定这个故事'):tr('Set up my real-life profile','建立真实财务档案')}</button></div></form>`}`);}
function emergencyModal(){const p=profile();if(!p){onboardStep=0;formDraft=defaultProfile();onboarding();return;}const cap=E.capacity(p);openModal(tr('A safety net, at your own pace','按自己的节奏，织一张安全网'),`<div class="story-preview-art">${miniArt('plant')}</div><p class="small muted">${tr('A parallel plan, separate from your main story. One deposit can be split between goals, but never counted twice. Missing an optional contribution will not lock your main story.','独立于主线故事的并行计划。一笔存款可分配给不同目标，但不会重复计算。未完成可选供款不会锁住主线故事。')}</p><form id="emergency-form" class="mt"><label class="check"><input type="checkbox" name="enabled" ${state.emergency.enabled?'checked':''}>${tr('Keep an emergency plan alongside my story','与故事并行保留应急计划')}</label><div class="form-grid mt">${field(tr('Monthly contribution','每月供款'),'monthly',p.emergency)}${select(tr('Core expense coverage target','核心开支保障目标'),'months',String(state.emergency.months),[['1',tr('1 month','1个月')],['3',tr('3 months','3个月')],['6',tr('6 months','6个月')],['12',tr('12 months','12个月')]])}</div><p class="small muted mt12">${tr(`Before the emergency allocation, your monthly saving room is ${cash(Math.max(0,cap.raw+p.emergency))}. This contribution is deducted once from main-story capacity.`,`应急分配前，你的每月储蓄空间为${cash(cap.available+p.emergency)}。此供款只会从主线储蓄能力中扣除一次。`)}</p>${formError}<div class="form-actions"><button type="submit" class="btn">${tr('Keep growing my safety net','继续积累安全网')}</button></div></form>`);}
function depositModal(){const p=profile();if(!p){toast(tr('Set up your financial profile first.','请先建立财务档案。'));return;}const s=active(),required=s?.current?Math.max(0,s.current.requiredTotal-E.allocation(state,s.id,s.currency)):0;openModal(tr('One small step, recorded','记录小小一步'),`<p class="small muted">${tr('Transfer money to your own bank account first. Record one transfer or a grouped batch below. No money moves through this app.','请先将资金转入你自己的银行账户。在下方记录一笔转账或合并批次。此应用不会转移资金。')}</p><form id="deposit-form" class="mt"><div class="form-grid">${field(tr('Actual transferred amount','真实转账金额'),'amount','','number','','required min="0.01"')}${select(tr('Transaction currency','交易币种'),'currency',s?.currency||p.currency,[['MYR','MYR · RM'],['SGD','SGD · S$']])}${field(tr('Actual transfer date','真实转账日期'),'date',E.today(),'date','',`required max="${E.today()}"`)}${field(tr('Unique transfer / batch reference','唯一转账／批次参考号'),'reference','','text','','required minlength="3" maxlength="100"')}${field(tr('Allocate to main story','分配至主线故事'),'main',required,'number',s?tx(story(s.story).title):tr('Start a main story to allocate here.','开始主线故事后即可分配。'),s?'':'disabled')}${field(tr('Allocate to emergency fund','分配至应急基金'),'emergency',0,'number',state.emergency.enabled?tr('Separate from the story allocation.','独立于故事分配。'):tr('Enable your emergency plan first.','请先启用应急计划。'),state.emergency.enabled?'':'disabled')}</div><label class="upload mt">${icon('upload')}<div class="bold small">${tr('Add evidence, if you have it','如有凭证，可在此添加')}</div><div class="small muted mt8">${tr('PNG, JPG or PDF · up to 5 MB · stored on this device','PNG、JPG或PDF · 最大5 MB · 保存在此设备')}</div><input name="receipt" type="file" accept="image/png,image/jpeg,application/pdf" aria-label="${tr('Savings evidence file','储蓄凭证文件')}"></label><label class="check mt"><input name="consent" type="checkbox" required>${tr('This is a new contribution, not savings already included in my starting balances. I transferred it to my own account.','这是一笔新增储蓄，不包含在起始余额中。我已将其转入自己的账户。')}</label>${formError}<div class="form-actions"><button type="submit" class="btn">${tr('Submit for local review','提交本地审阅')}</button></div></form>`);}
function reviewModal(id){const t=state.ledger.find(t=>t.id===id);if(!t||t.status!=='pending')return;openModal(tr('A moment to check your record','花一点时间，检查记录'),`${notice(tr('This is local self-confirmation. No bank or independent reviewer has verified this transfer.','这是本地自行确认，没有银行或独立审核员验证此转账。'),'warn')}<div class="cost-list mt"><div class="cost-row"><span>${esc(t.reference)}</span><strong>${cash(t.amount,t.currency)}</strong></div><div class="cost-row"><span>${tr('Story allocation','故事分配')}</span><strong>${cash(t.main,t.currency)}</strong></div><div class="cost-row"><span>${tr('Emergency allocation','应急分配')}</span><strong>${cash(t.emergency,t.currency)}</strong></div></div>${t.fileName?`<button class="textbtn mt12" data-action="evidence:${id}">${tr('View the evidence I uploaded','查看我上传的凭证')}</button>`:''}<form id="review-form" data-id="${id}"><label class="check mt"><input type="checkbox" required name="ack">${tr('I checked my own transfer and confirm this amount is accurate. I understand this is not bank verification.','我已检查自己的转账，确认金额准确，并理解这不是银行验证。')}</label>${formError}<div class="form-actions">${button(tr('Reject record','拒绝记录'),`reject:${id}`,'secondary','type="button"')}<button class="btn" type="submit">${tr('Self-confirm this deposit','自行确认此存款')}</button></div></form>`);}
async function evidenceStore(action,key,file){const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('save-your-story-evidence',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});try{return await new Promise((resolve,reject)=>{const t=db.transaction('files',action==='get'?'readonly':'readwrite'),store=t.objectStore('files'),r=action==='put'?store.put(file,key):action==='clear'?store.clear():store.get(key);let value;r.onsuccess=()=>value=r.result;t.oncomplete=()=>resolve(value);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});}finally{db.close();}}
function adjustCheckpointModal(){const s=active(),p=profile();if(!s?.current)return;openModal(tr('Give this chapter more room','给这一章多些空间'),`<p class="small muted">${tr('Lower an optional game checkpoint or extend preparation when your real situation changes. The simulated expense remains visible. Completing a lower target does not make the original commitment affordable.','真实情况改变时，可以降低可选游戏目标或延长准备期。模拟开支仍清晰显示。完成较低目标不表示能负担原计划。')}</p><form id="adjust-form" class="mt"><div class="form-grid">${field(tr('Revised savings checkpoint','调整后的储蓄目标'),'target',Math.min(s.current.target,E.capacity(p).available),'number','',`max="${s.current.target}" required`)}${field(tr('Additional preparation days','新增准备天数'),'extraDays',30,'number','','min="0" max="3650" step="1" required')}</div>${formError}<div class="form-actions"><button type="submit" class="btn">${tr('Save my adjustment','保存我的调整')}</button></div></form>`);}
function formValues(form){const d=Object.fromEntries(new FormData(form));for(const el of form.querySelectorAll('input[type="number"]'))if(!el.disabled)d[el.name]=Number(el.value);for(const el of form.querySelectorAll('input[type="checkbox"]'))d[el.name]=el.checked;return d;}
function updateDraft(form){formDraft={...formDraft,...formValues(form)};}
let pendingStart=null,restoredState=null;
function startReview(config){const p=profile(),st=story(previewId),temp=E.newSession(previewId,p,config,()=>.99),cost=previewId==='car'?E.carCosts(temp.config):null,budget=previewId==='travel'?E.travelBudget(temp):previewId==='baby'?chaptersFor('baby',p.country,config).reduce((n,_,i)=>n+E.itemTotal(E.budgetItems(temp,i)),0):0;pendingStart={story:previewId,config};const cap=E.capacity(p).available;openModal(tr('Before you turn the first page','翻开第一页之前'),`<div class="story-preview-art">${miniArt(st.icon)}</div><h3>${tx(st.title)}</h3><div class="cost-list mt"><div class="cost-row"><span>${tr('Estimated story duration','估计故事时长')}</span><strong>${previewId==='travel'?`${config.days} ${tr('days','天')}`:tx(st.duration)}</strong></div><div class="cost-row"><span>${tr('Your current monthly savings capacity','当前每月储蓄能力')}</span><strong>${cash(cap)}</strong></div>${cost?`<div class="cost-row"><span>${tr('Sample upfront costs','模拟前期成本')}</span><strong>${cash(cost.upfront)}</strong></div><div class="cost-row"><span>${tr('Additional monthly car responsibility','每月新增拥车责任')}</span><strong>${cash(cost.additional)}</strong></div>`:`<div class="cost-row"><span>${tr('Illustrative story expense total','故事模拟开支总额')}</span><strong>${cash(budget)}</strong></div>`}</div>${cost&&cost.additional>cap?`<div class="mt12">${notice(tr(`Monthly shortfall: ${cash(cost.additional-cap)}. Choose a cheaper car, increase your own down payment, revise assumptions, prepare longer, or postpone. A capped rehearsal is not proof of affordability.`,`每月短缺：${cash(cost.additional-cap)}。可选便宜车辆、用自有资金提高首付、修改假设、延长准备期或推迟。受限储蓄演练不能证明能负担。`),'warn')}</div>`:''}${previewId==='travel'?`<div class="mt">${scheduleTable(temp)}</div>`:''}${previewId==='baby'?`<div class="mt12">${notice(tr('Care timing and quotations are individual. Twin costs change only relevant items. This is a budgeting journey through the third birthday, not medical guidance.','照护时间和报价因人而异。双胎仅调整相关项目。此预算旅程持续至三岁生日，不是医疗指导。'),'blue')}</div>`:''}<p class="small muted mt">${tr('Starting locks one main story until completion. The emergency plan remains optional. Virtual costs never deduct real savings.','开始后会锁定一个主线故事直到完成。应急计划保持可选。虚拟成本不会扣减真实储蓄。')}</p><div class="form-actions">${button(tr('Adjust my plan','调整我的计划'),`preview:${previewId}`,'secondary')}${button(tr('Begin this chapter','开始这一章'),'confirmstart')}</div>`);}
async function action(a){const [kind,id,extra]=a.split(':');if(kind==='nav'){closeModal();navigate(id);return;}if(kind==='close'){closeModal();return;}if(kind==='language'){state.language=state.language==='en'?'zh':'en';save();closeModal();render();return;}if(kind==='adjustcheckpoint'){adjustCheckpointModal();return;}if(kind==='onboard'){if(profile()){storyView='library';navigate('story');return;}formDraft=defaultProfile();onboardStep=0;onboarding();return;}if(kind==='onboardback'){updateDraft($('#onboard-form'));onboardStep=Math.max(0,onboardStep-1);onboarding();return;}if(kind==='sample'){updateDraft($('#onboard-form'));const sg=formDraft.country==='SG';formDraft={...formDraft,income:sg?4500:5000,fixed:sg?1100:1000,living:sg?900:1000,discretionary:300,loans:sg?200:300,savings:1000,reserves:500,emergency:200,loanBalance:12000,assets:0};onboarding();toast(tr('Sample amounts loaded. Replace them with your own before saving.','已载入示例金额。保存前请替换为你自己的数字。'));return;}if(kind==='editprofile'){editProfile();return;}if(kind==='library'){storyView='library';navigate('story');return;}if(kind==='storyview'){storyView=id;render();return;}if(kind==='financeview'){financeView=id;render();return;}if(kind==='preview'){preview(id);return;}if(kind==='emergency'){emergencyModal();return;}if(kind==='confirmstart'){if(!pendingStart)throw Error('Preview a story first.');if(active()&&!active().completed)throw Error('Your main story is still active.');const p=profile(),s=E.newSession(pendingStart.story,p,pendingStart.config);state.sessions.push(s);state.activeId=s.id;pendingStart=null;save();closeModal();storyView='journal';navigate('story');return;}if(kind==='decide'){const s=active(),p=profile();if(s.currency!==p.currency)throw Error(tr('Your active profile uses a different currency. Restore a profile in this story’s currency before making a new decision.','当前档案币种不同。请先恢复与故事相同币种的档案，再作新决定。'));E.decide(s,p,id);save();render();toast(tr('Your choice is written into the story.','你的选择已写进故事。'));return;}if(kind==='clock'){const s=active();s.clock=Math.max(s.clock,s.current.dueDay);save();render();toast(tr('The story calendar moved forward. Your real financial profile did not change.','故事日历已推进。真实财务档案没有改变。'));return;}if(kind==='advance'){E.advance(state,active());save();render();window.scrollTo({top:0,behavior:'smooth'});toast(tr('A new page, shaped by your choices.','新的一页，由你的选择塑造。'));return;}if(kind==='event'){E.resolveEvent(active(),id,extra);save();render();toast(tr('Your response is saved in this journey.','你的应对已保存。'));return;}if(kind==='deposit'){depositModal();return;}if(kind==='review'){reviewModal(id);return;}if(kind==='reject'){const t=state.ledger.find(t=>t.id===id);if(t?.status==='pending')t.status='rejected';save();closeModal();render();return;}if(kind==='evidence'){const file=await evidenceStore('get',id);if(!file)throw Error(tr('This receipt file is not on this browser. Backup exports contain records only.','此浏览器中没有该凭证文件。导出备份只包含记录。'));const url=URL.createObjectURL(file);const receiptWindow=window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);return;}if(kind==='carfinance'){closeModal();financeView='car';navigate('finance');return;}if(kind==='homefinance'){closeModal();financeView='property';navigate('finance');return;}if(kind==='applycar'){const s=active();if(!s||s.story!=='car'){preview('car');return;}if(s.current)throw Error(tr('A decision is already frozen for this chapter. Apply new assumptions after turning the page.','本章决定已保存。翻页后再应用新假设。'));if(s.country!==profile().country)throw Error('Country does not match the active story.');s.config={...carDraft};save();toast(tr('Future car assumptions updated. Completed chapters stay unchanged.','未来车辆假设已更新。已完成章节保持不变。'));return;}if(kind==='costs'){const s=active();if(s.current)throw Error('This chapter already has a saved cost snapshot.');const items=E.budgetItems(s);if(!items.length){toast(tr('No separate cost items in this scene. Use Finance for car ownership assumptions.','本场景没有独立成本项目。拥车假设可在财务中修改。'));return;}openModal(tr('Your own quotations come first','优先使用你的报价'),`<p class="small muted">${tr('Enter a unit quotation. Quantity is applied separately. New quotations affect only this future chapter; completed costs remain frozen.','输入单位报价，数量另计。新报价仅影响此未来章节，已完成成本保持不变。')}</p><form id="cost-form" class="mt"><div class="form-grid">${items.map(i=>field(tx(i.label)+` · ×${i.quantity}`,i.id,i.quote??i.typical,'number',tr(`Illustrative range ${cash(i.min,i.currency)}–${cash(i.max,i.currency)} · no provider verification`,`模拟范围${cash(i.min,i.currency)}–${cash(i.max,i.currency)} · 未经供应商核实`))).join('')}</div>${formError}<div class="form-actions"><button class="btn" type="submit">${tr('Keep my quotations','保存我的报价')}</button></div></form>`);return;}if(kind==='name'){openModal(tr('A name for your journal','日记中的称呼'),`<form id="name-form">${field(tr('Your name','你的名字'),'name',state.name,'text','','required maxlength="40"')}${formError}<div class="form-actions"><button type="submit" class="btn">${tr('Save name','保存称呼')}</button></div></form>`);return;}if(kind==='reminders'){const s=active();openModal(tr('A gentle reminder','一个温柔的提醒'),s?.current?`<p>${tr('Your next Savings Day is waiting in your current chapter.','下一储蓄日正等在当前章节。')}</p><p class="metric mt">${cash(Math.max(0,s.current.requiredTotal-E.allocation(state,s.id,s.currency)),s.currency)}</p><p class="small muted mt12">${tr('Remaining self-recorded savings needed. Go at a pace that protects your everyday.','剩余需要自行记录的储蓄。请按能保障日常生活的节奏进行。')}</p><div class="mt">${button(tr('Open Savings Day','打开储蓄日'),'nav:savings')}</div>`:`<div class="text-center">${miniArt('plant')}<p>${tr('No savings checkpoint is due yet. A new story is a good place to begin.','目前没有到期的储蓄点。可以从新故事开始。')}</p><div class="mt">${button(tr('Explore stories','探索故事'),'library')}</div></div>`);return;}if(kind==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`save-your-story-${E.today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);toast(tr('Backup exported. Receipt files are not included.','备份已导出，不包含凭证文件。'));return;}if(kind==='import'){openModal(tr('Restore your journal','恢复你的日记'),`<p class="small muted">${tr('Select a Save Your Story JSON backup. You will review its summary before replacing the current journal. Receipt files are not restored.','选择Save Your Story JSON备份。替换当前日记前会显示摘要。凭证文件不会恢复。')}</p><form id="import-form" class="mt"><label class="upload"><input name="backup" type="file" accept="application/json,.json" required aria-label="${tr('Journal backup','日记备份')}"></label>${formError}<div class="form-actions"><button type="submit" class="btn">${tr('Review backup','审阅备份')}</button></div></form>`);return;}if(kind==='confirmimport'){if(!restoredState)return;state=restoredState;restoredState=null;save();closeModal();render();toast(tr('Your journal has been restored.','你的日记已恢复。'));return;}if(kind==='reset'){openModal(tr('Delete this local journal?','删除此本地日记？'),`<p>${tr('This removes financial profiles, story decisions, contribution records and uploaded evidence from this browser. Export a backup first if you want to keep your records.','这将删除此浏览器中的财务档案、故事决定、储蓄记录及上传凭证。如需保留记录，请先导出备份。')}</p><div class="form-actions">${button(tr('Keep my journal','保留日记'),'close','secondary')}${button(tr('Delete local data','删除本地数据'),'confirmreset')}</div>`);return;}if(kind==='confirmreset'){await evidenceStore('clear');localStorage.removeItem(KEY);state=E.initialState();carDraft=null;propertyDraft=null;closeModal();navigate('home');toast(tr('Local journal and evidence deleted.','本地日记及凭证已删除。'));return;}}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;ev.preventDefault();try{await action(b.dataset.action);}catch(e){const err=$('#modal[open] .form-error');if(err)err.textContent=e.message;else toast(e.message);}});
document.addEventListener('change',ev=>{if(ev.target.id==='notifications'){state.notifications=ev.target.checked;save();return;}if(ev.target.closest('#onboard-form')&&['language','country'].includes(ev.target.name)){updateDraft($('#onboard-form'));if(ev.target.name==='language')state.language=ev.target.value;formDraft.currency=formDraft.country==='SG'?'SGD':'MYR';onboarding();render();}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target,d=formValues(f),submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{
if(f.id==='onboard-form'){updateDraft(f);state.name=String(formDraft.name||'Alex').trim();if(onboardStep<2){onboardStep++;onboarding();return;}const draftCap=E.capacity({...formDraft,currency:formDraft.country==='SG'?'SGD':'MYR'});if(formDraft.emergency>Math.max(0,draftCap.raw+formDraft.emergency))throw Error(tr('Lower the optional emergency contribution to fit your available income.','请降低可选应急供款，使其在可用收入范围内。'));const p=E.profileVersion(state,{...formDraft,currency:formDraft.country==='SG'?'SGD':'MYR',effective:E.today(),excludedTransactionIds:[]});state.emergency={...state.emergency,enabled:p.emergency>0,monthly:p.emergency};state.onboarded=true;state.disclaimer=true;save();closeModal();storyView='library';navigate('story');return;}
if(f.id==='profile-form'){const p=profile();const updatedCap=E.capacity({...p,...d,currency:d.country==='SG'?'SGD':'MYR'});if(d.emergency>Math.max(0,updatedCap.raw+d.emergency))throw Error(tr('Lower the optional emergency contribution to fit the revised budget.','请降低可选应急供款，使其在调整后的预算范围内。'));if(d.country!==p.country&&(d.savings===formDraft.savings||d.reserves===formDraft.reserves))throw Error(tr('Changing expense currency needs explicitly revised savings and reserve balances in the new currency. Enter the actual balances.','更改支出币种后，请明确修改为新币种的真实储蓄及储备余额。'));E.profileVersion(state,{...p,...d,currency:d.country==='SG'?'SGD':'MYR',excludedTransactionIds:state.ledger.filter(t=>t.status==='confirmed').map(t=>t.id)});state.emergency.enabled=d.emergency>0||state.emergency.enabled;state.emergency.monthly=d.emergency;save();closeModal();render();toast(tr('A new dated financial profile is saved.','新的带日期财务档案已保存。'));return;}
if(f.id==='start-form'){if(!profile()){closeModal();formDraft=defaultProfile();onboardStep=0;onboarding();return;}let config=d;delete config.lockack;if(previewId==='car'){if(d.down>d.price||d.price<=0||d.years<1||d.years>15)throw Error(tr('Use a positive vehicle price, a down payment no greater than the price, and 1–15 loan years.','请输入正数车价、低于或等于车价的首付，及1–15年贷款。'));}if(previewId==='travel'){const days=Math.round((new Date(d.departure+'T12:00:00Z')-new Date(E.today()+'T12:00:00Z'))/86400000);if(days<30||days>365||d.flightDay>=d.hotelDay||d.hotelDay>days||d.travellers<1||d.flightDay<1)throw Error(tr('Use 30–365 days until departure, with flights before hotel payment and both before departure.','出发时间须在30–365天内，机票付款须早于住宿付款，两者都在出发前。'));const budget={};for(const k of Object.keys(d).filter(k=>k.startsWith('budget_')))budget[k.slice(7)]=d[k];config={destination:d.destination,travellers:d.travellers,departure:d.departure,travelDays:d.travelDays,style:d.style,existing:d.existing,days,flightDay:d.flightDay,hotelDay:d.hotelDay,budget};}startReview(config);return;}
if(f.id==='car-form'){if(d.price<=0||d.down>d.price||d.years<1||d.years>15)throw Error(tr('Check the vehicle price, down payment, and loan term.','请检查车价、首付和贷款年限。'));carDraft={...carDraft,...d,country:profile().country};render();return;}
if(f.id==='property-form'){if(d.price<=0||d.down>d.price||d.years<1||d.years>40)throw Error(tr('Check property price, down payment, and a 1–40 year term.','请检查房价、首付及1–40年贷款年限。'));propertyDraft={...d,country:profile().country};render();return;}
if(f.id==='emergency-form'){const p=profile(),room=Math.max(0,E.capacity(p).raw+p.emergency),con=d.enabled?d.monthly:0;if(con>room+.005)throw Error(tr('The combined savings plan exceeds your entered capacity. Lower the optional contribution.','组合储蓄计划超出你输入的能力，请降低可选供款。'));const cur=active()?.current;if(cur&&con>p.emergency&&cur.target+con>room+.005)throw Error(tr('This chapter already has a savings checkpoint. Keep the combined plan within capacity, or adjust after the chapter.','本章已有储蓄目标。请保持组合计划在能力范围内，或完成本章后再调整。'));E.profileVersion(state,{...p,emergency:con,savings:E.recordedSavings(state,p),reserves:E.reserves(state,p),effective:E.today(),excludedTransactionIds:state.ledger.filter(t=>t.status==='confirmed').map(t=>t.id)});state.emergency={enabled:d.enabled,monthly:con,months:Number(d.months)};save();closeModal();render();return;}
if(f.id==='cost-form'){const s=active();if(s.current)throw Error('This chapter snapshot is already saved.');for(const [id,v]of Object.entries(d)){if(!Number.isFinite(v)||v<0)throw Error('Enter valid quotations.');s.costOverrides[`${s.index}:${id}`]=v;}save();closeModal();render();return;}
if(f.id==='deposit-form'){const file=f.querySelector('[name="receipt"]').files[0];let hash=null;if(file){if(file.size>5*1024*1024||!['image/png','image/jpeg','application/pdf'].includes(file.type))throw Error(tr('Choose a PNG, JPG or PDF smaller than 5 MB.','请选择小于5 MB的PNG、JPG或PDF。'));const bytes=await file.arrayBuffer();hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join('');}if(d.emergency>0&&d.currency!==profile().currency)throw Error(tr('Emergency allocations must match your current profile currency.','应急分配须与当前档案币种相同。'));const entry=E.submitTransaction(state,{amount:d.amount,main:d.main||0,emergency:d.emergency||0,reference:d.reference,date:d.date,currency:d.currency,storyId:active()?.id||null,fileName:file?.name||null,hash});try{if(file)await evidenceStore('put',entry.id,file);}catch(e){state.ledger=state.ledger.filter(t=>t.id!==entry.id);throw Error(tr('The evidence file could not be saved on this device. No contribution was recorded.','凭证文件无法保存在此设备。没有记录任何供款。'));}save();closeModal();page='savings';render();reviewModal(entry.id);return;}
if(f.id==='review-form'){E.confirmTransaction(state,f.dataset.id);save();closeModal();render();toast(tr('Your contribution is self-confirmed in this local demo.','你的供款已在本地演示中自行确认。'));return;}
if(f.id==='adjust-form'){E.reviseCheckpoint(active(),profile(),d.target,d.extraDays);save();closeModal();render();return;}if(f.id==='name-form'){state.name=d.name.trim()||'Alex';save();closeModal();render();return;}
if(f.id==='import-form'){const file=f.querySelector('[name="backup"]').files[0];if(file.size>5*1024*1024)throw Error('Backup is too large.');restoredState=E.validateImport(JSON.parse(await file.text()));openModal(tr('Restore this journal?','恢复此日记？'),`<p>${esc(restoredState.name)} · ${restoredState.sessions.length} ${tr('stories','个故事')} · ${restoredState.ledger.length} ${tr('contribution records','条供款记录')}</p><p class="small muted mt12">${tr('This replaces your current journal on this browser. Local receipt files are not part of the backup.','这将替换此浏览器中的当前日记。本地凭证文件不包含在备份中。')}</p><div class="form-actions">${button(tr('Cancel','取消'),'close','secondary')}${button(tr('Replace & restore','替换并恢复'),'confirmimport')}</div>`);return;}
}catch(e){const err=f.querySelector('.form-error');if(err)err.textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}});
render();
if(state.notifications&&active()?.current)setTimeout(()=>toast(tr('A gentle nudge: your Savings Day is waiting in your journal.','温柔提醒：储蓄日正在日记中等你。')),1200);
